import React, { useState, useEffect, useCallback } from 'react';
import { apiClient, ApiError } from '../../api/client';
import type { DetectionRule, SecurityAlert } from '../../types/api';
import { ErrorState, LoadingState, EmptyState } from '../common/StateView';
import { SeverityBadge } from '../common/SeverityBadge';
import { StatusBadge } from '../common/StatusBadge';
import { RiskScorePill } from '../common/RiskScorePill';
import { Pagination } from '../common/Pagination';
import { RefreshCw, Shield, Zap } from 'lucide-react';

// Threat Detection view — shows alerts generated by the detection engine
// with filtering by rule and severity, plus a quick run-detections panel
export const ThreatDetectionView: React.FC = () => {
  const [alerts, setAlerts] = useState<SecurityAlert[]>([]);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [page, setPage] = useState(0);
  const [filterSeverity, setFilterSeverity] = useState('');
  const [filterRule, setFilterRule] = useState('');
  const [ruleOptions, setRuleOptions] = useState<DetectionRule[]>([]);
  const [runningDet, setRunningDet] = useState(false);
  const [detMsg, setDetMsg] = useState<string | null>(null);
  const limit = 20;

  const load = useCallback(() => {
    setLoading(true);
    setError(null);
    apiClient.getAlerts({ limit, offset: page * limit, severity: filterSeverity || undefined, rule_id: filterRule || undefined })
      .then((r) => { setAlerts(r.items); setTotal(r.total); setLoading(false); })
      .catch((e: any) => { setError(e instanceof ApiError ? e.message : 'Failed to load alerts'); setLoading(false); });
  }, [page, filterSeverity, filterRule]);

  useEffect(() => { load(); }, [load]);

  // Rule filter options come from the real detection engine
  // (GET /api/v1/detections/rules), merged with rule IDs present in loaded alerts.
  useEffect(() => {
    if (typeof apiClient.getDetectionRules !== 'function') return;
    apiClient
      .getDetectionRules()
      .then((r) => { setRuleOptions(r.rules); })
      .catch(() => {});
  }, []);

  const ruleIds = Array.from(
    new Set([...ruleOptions.map((r) => r.rule_id), ...alerts.map((a) => a.rule_id)])
  );

  const handleRunDetections = async () => {
    setRunningDet(true);
    setDetMsg(null);
    try {
      const r = await apiClient.runDetections({ limit: 500, lookback_minutes: 120 });
      setDetMsg(`Detection run complete: ${r.alerts_created} new alerts, ${r.alerts_updated} updated, ${r.events_evaluated} events evaluated.`);
      load();
    } catch (e: any) {
      setDetMsg(`Detection run failed: ${e.message}`);
    } finally {
      setRunningDet(false);
    }
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.5rem' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: '0.75rem' }}>
        <div>
          <h2 style={{ fontSize: '1.1rem', fontWeight: 700, color: '#f1f5f9', display: 'flex', alignItems: 'center', gap: '0.5rem' }}>
            <Shield size={18} /> Threat Detection
          </h2>
          <p style={{ fontSize: '0.8rem', color: '#64748b', marginTop: '0.2rem' }}>
            Alerts generated by the deterministic detection engine
          </p>
        </div>
        <div style={{ display: 'flex', gap: '0.75rem' }}>
          <button className="btn btn-secondary" onClick={load} disabled={loading}>
            <RefreshCw size={14} className={loading ? 'spin' : ''} /> Refresh
          </button>
          <button className="btn btn-primary" onClick={handleRunDetections} disabled={runningDet}>
            <Zap size={14} className={runningDet ? 'spin' : ''} /> Run Detection Engine
          </button>
        </div>
      </div>

      {detMsg && (
        <div style={{ padding: '0.75rem 1rem', borderRadius: 8, background: 'rgba(59,130,246,0.08)', border: '1px solid rgba(59,130,246,0.3)', color: '#93c5fd', fontSize: '0.82rem' }}>
          {detMsg}
        </div>
      )}

      {/* Filters */}
      <div className="toolbar-row">
        <select className="select-field" value={filterSeverity} onChange={(e) => { setFilterSeverity(e.target.value); setPage(0); }}>
          <option value="">All Severities</option>
          {['CRITICAL', 'HIGH', 'MEDIUM', 'LOW', 'INFORMATIONAL'].map((s) => <option key={s}>{s}</option>)}
        </select>
        <select
          className="select-field"
          value={filterRule}
          onChange={(e) => { setFilterRule(e.target.value); setPage(0); }}
          aria-label="Filter by rule ID"
        >
          <option value="">All Rules</option>
          {ruleIds.map((rid) => {
            const meta = ruleOptions.find((r) => r.rule_id === rid);
            return (
              <option key={rid} value={rid}>
                {rid} · {meta ? meta.rule_name : 'detection rule'}
              </option>
            );
          })}
        </select>
      </div>

      <div className="panel-card" style={{ padding: 0 }}>
        {loading ? <LoadingState message="Loading threat alerts..." /> :
          error ? <ErrorState message={error} onRetry={load} /> :
          alerts.length === 0 ? (
            <EmptyState
              icon={<Shield size={36} />}
              message="No alerts match your filters."
              sub="Run the detection engine to generate alerts from recent events."
            />
          ) : (
            <>
              <div className="table-responsive">
                <table className="data-table">
                  <thead>
                    <tr>
                      <th>Severity</th>
                      <th>Title</th>
                      <th>Rule</th>
                      <th>Risk</th>
                      <th>Status</th>
                      <th>Occurrences</th>
                      <th>First Seen</th>
                    </tr>
                  </thead>
                  <tbody>
                    {alerts.map((a) => (
                      <tr key={a.alert_id}>
                        <td><SeverityBadge severity={a.severity} /></td>
                        <td style={{ maxWidth: 280 }}>
                          <div style={{ color: '#f1f5f9', fontWeight: 500, fontSize: '0.85rem', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{a.title}</div>
                          <div style={{ color: '#64748b', fontSize: '0.72rem' }}>{a.description.substring(0, 80)}{a.description.length > 80 ? '...' : ''}</div>
                        </td>
                        <td style={{ fontFamily: 'monospace', fontSize: '0.75rem', color: '#38bdf8' }}>{a.rule_id}</td>
                        <td><RiskScorePill score={a.risk_score} /></td>
                        <td><StatusBadge status={a.status} /></td>
                        <td style={{ color: '#94a3b8', fontSize: '0.82rem', textAlign: 'center' }}>{a.occurrence_count}</td>
                        <td style={{ color: '#64748b', fontSize: '0.78rem', whiteSpace: 'nowrap' }}>
                          {new Date(a.first_seen).toLocaleString()}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
              <div style={{ padding: '1rem 1.5rem', borderTop: '1px solid #1e2638' }}>
                <Pagination total={total} limit={limit} offset={page * limit} onPageChange={(o) => setPage(Math.floor(o / limit))} />
              </div>
            </>
          )}
      </div>
    </div>
  );
};

